#!/usr/bin/env node

// ==========================================================================
// CUSTOM DEMO PAGE GENERATOR CLI
// ==========================================================================
// Generates custom demo pages in user's project that merge master features
// from ULS package with user's custom features.
// 
// Usage: 
//   npm run uls-create-custom-demo -- --component=Card
//   npm run uls-create-custom-demo -- Card
//   node scripts/create-custom-demo.js --component=Card --demo-name=CardDemo

import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

// ==========================================================================
// TEMPLATES
// ==========================================================================

const TEMPLATES = {
    features: `import React from 'react';
import DocPanel from '../../Components/Common/DocMain/DocPanel';
import CodePreview from '../../Components/Common/CodePreview';
import RichText from '../../Components/Common/RichText';
import { mergeFeatures } from '../../utils/featureMerger';

// Import master features from ULS package
import { {{ComponentName}}FeatureItems as Master{{ComponentName}}FeatureItems } from '../../Pages/Documentation/UiComponents/{{ComponentName}}Page/features';

// Import your custom demos from custom-components
import { 
    CustomBasicDemo,
    CustomBasicSource,
} from './import';

// Define your custom features
const Custom{{ComponentName}}FeatureItems = [
    {
        id: "custom-basic",
        sectionNav: "Custom Basic",
        sectionDesc: <RichText as="span" content="Your custom basic demo description." />,
        demo: (
            <CodePreview 
                demo={<CustomBasicDemo />} 
                source={CustomBasicSource} 
                snippetName="custom-basic" 
                language="jsx" 
            />
        ),
    },
];

// Merge master and custom features
export const {{ComponentName}}FeatureItems = mergeFeatures(
    Master{{ComponentName}}FeatureItems,
    Custom{{ComponentName}}FeatureItems
);

// Export component for direct use
export default function {{ComponentName}}Features() {
    return (
        <DocPanel 
            Header="{{ComponentName}}" 
            SubHeader="{{ComponentName}} is a flexible container component." 
            features={{{ComponentName}}FeatureItems}
        />
    );
}`,

    import: `// ==========================================================================
// Custom Demo Components Barrel Export
// ==========================================================================
// Imports custom demo components from custom-components folder

// Custom Basic Demo
export { default as CustomBasicDemo } from '../../custom-components/{{ComponentName}}/CustomBasicDemo';
export { default as CustomBasicSource } from '../../custom-components/{{ComponentName}}/CustomBasicDemo/CustomBasicDemo.jsx?raw';
`,

    demoPage: `import React from 'react';
import DocPanel from '../../Components/Common/DocMain/DocPanel';
import { {{ComponentName}}FeatureItems } from './features';

export default function {{DemoName}}Page() {
    return (
        <DocPanel 
            Header="{{ComponentName}} Demo" 
            SubHeader="Extended {{ComponentName}} Demo with Custom Features" 
            features={{{ComponentName}}FeatureItems}
        />
    );
}`,

    customComponent: `import React from 'react';
import { {{ComponentName}} } from 'primereact/{{primereactName}}';

export default function CustomBasicDemo() {
    return (
        <div className="p-4">
            <{{ComponentName}}>
                Custom {{ComponentName}} Demo
            </{{ComponentName}}>
        </div>
    );
}`,

    versionInfo: `{
  "ulsVersion": "{{ULS_VERSION}}",
  "demoVersion": "1.0.0",
  "lastSync": "{{TIMESTAMP}}",
  "history": [
    {
      "demoVersion": "1.0.0",
      "ulsVersion": "{{ULS_VERSION}}",
      "created": "{{TIMESTAMP}}",
      "changes": "Initial custom demo page creation"
    }
  ],
  "masterSnapshot": []
}
`
};

// ==========================================================================
// UTILITY FUNCTIONS
// ==========================================================================

function replaceTemplateVariables(template, variables) {
    let result = template;
    Object.entries(variables).forEach(([key, value]) => {
        const regex = new RegExp(`{{${key}}}`, 'g');
        result = result.replace(regex, value || '');
    });
    return result;
}

function generateComponentVariations(componentName) {
    const pascalCase = componentName.charAt(0).toUpperCase() + componentName.slice(1);
    const camelCase = componentName.charAt(0).toLowerCase() + componentName.slice(1);
    const kebabCase = componentName.toLowerCase().replace(/([A-Z])/g, '-$1').toLowerCase();
    
    return {
        ComponentName: pascalCase,
        componentName: camelCase,
        'component-name': kebabCase,
        primereactName: kebabCase
    };
}

function getArgValue(args, key) {
    const index = args.findIndex(arg => arg.startsWith(key));
    if (index === -1) return null;
    
    const value = args[index];
    if (value.includes('=')) {
        return value.split('=')[1];
    }
    return args[index + 1] || null;
}

function findULSPackage() {
    const projectRoot = process.cwd();
    
    // Try to find ULS package in different locations
    const candidates = [
        // If ULS is installed as npm package
        path.resolve(projectRoot, 'node_modules/uls-v2'),
        // If running from ULS development workspace
        path.resolve(__dirname, '..'),
        // Alternative package name
        path.resolve(projectRoot, 'node_modules/@uls/v2'),
    ];
    
    for (const candidate of candidates) {
        const primereactPath = path.join(candidate, 'src/libs/uls-primereact');
        if (fs.existsSync(primereactPath)) {
            return candidate;
        }
    }
    
    return null;
}

function getULSVersion() {
    const ulsPackage = findULSPackage();
    if (!ulsPackage) {
        return 'unknown';
    }
    
    const packageJsonPath = path.join(ulsPackage, 'package.json');
    if (fs.existsSync(packageJsonPath)) {
        try {
            const pkg = JSON.parse(fs.readFileSync(packageJsonPath, 'utf8'));
            return pkg.version || 'unknown';
        } catch (error) {
            return 'unknown';
        }
    }
    return 'unknown';
}

function validateComponentExists(componentName) {
    const ulsPackage = findULSPackage();
    
    if (!ulsPackage) {
        throw new Error(
            'ULS package not found. Make sure uls-v2 is installed in node_modules or ' +
            'you are running from the ULS development workspace.'
        );
    }
    
    const componentPagePath = path.join(
        ulsPackage,
        'src/libs/uls-primereact/src/Pages/Documentation/UiComponents',
        `${componentName}Page`
    );

    if (!fs.existsSync(componentPagePath)) {
        throw new Error(
            `Component "${componentName}" not found in ULS package.\n` +
            `Expected path: ${componentPagePath}\n` +
            `Make sure the component exists in ULS package.`
        );
    }

    // Check if features.jsx exists
    const featuresPath = path.join(componentPagePath, 'features.jsx');
    if (!fs.existsSync(featuresPath)) {
        throw new Error(
            `Features file not found for component "${componentName}".\n` +
            `Expected: ${featuresPath}`
        );
    }

    return true;
}

// ==========================================================================
// MAIN GENERATOR FUNCTION
// ==========================================================================

async function createCustomDemo() {
    try {
        // Parse command line args
        const args = process.argv.slice(2);
        let componentName = getArgValue(args, '--component') || 
                           getArgValue(args, 'component');
        
        let demoName = getArgValue(args, '--demo-name') || 
                      getArgValue(args, '--name') ||
                      getArgValue(args, 'name');

        // If component name is provided as positional arg
        if (!componentName && args.length > 0 && !args[0].startsWith('--')) {
            componentName = args[0];
        }

        // Validate component name
        if (!componentName) {
            console.error('❌ Error: Component name is required');
            console.log('\nUsage:');
            console.log('  npm run uls-create-custom-demo -- --component=Card');
            console.log('  npm run uls-create-custom-demo -- Card');
            console.log('  node scripts/create-custom-demo.js --component=Card --demo-name=CardDemo');
            process.exit(1);
        }

        // Validate component exists in ULS
        validateComponentExists(componentName);

        // Set default demo name
        if (!demoName) {
            demoName = `${componentName}Demo`;
        }

        const variations = generateComponentVariations(componentName);
        const pageFolderName = `${variations.ComponentName}Page`;

        // Find uls-primereact directory
        const ulsPackage = findULSPackage();
        if (!ulsPackage) {
            throw new Error('ULS package not found. Make sure you are running from ULS workspace or uls-v2 is installed.');
        }
        
        const primereactPath = path.join(ulsPackage, 'src/libs/uls-primereact');
        if (!fs.existsSync(primereactPath)) {
            throw new Error(`uls-primereact not found at: ${primereactPath}`);
        }
        
        // Create paths inside uls-primereact
        const customDemoPath = path.join(primereactPath, 'src/custom-demo');
        const demoPagePath = path.join(customDemoPath, pageFolderName);
        const customComponentsPath = path.join(primereactPath, 'src/custom-components');
        const componentFolderPath = path.join(customComponentsPath, variations.ComponentName);
        const componentPath = path.join(componentFolderPath, 'CustomBasicDemo');

        // Check if already exists
        if (fs.existsSync(demoPagePath)) {
            console.warn(`⚠️  Demo page "${pageFolderName}" already exists at: ${demoPagePath}`);
            console.log('   Use --force to overwrite (not implemented yet)');
            process.exit(1);
        }

        // Create directories
        fs.mkdirSync(demoPagePath, { recursive: true });
        fs.mkdirSync(componentFolderPath, { recursive: true });
        fs.mkdirSync(componentPath, { recursive: true });
        console.log(`📁 Created directory: ${path.relative(process.cwd(), demoPagePath)}`);
        console.log(`📁 Created directory: ${path.relative(process.cwd(), componentFolderPath)}`);
        console.log(`📁 Created directory: ${path.relative(process.cwd(), componentPath)}`);

        // Get ULS version
        const ulsVersion = getULSVersion();
        const timestamp = new Date().toISOString();

        // Template variables
        const templateVars = {
            ...variations,
            DemoName: demoName,
            ULS_VERSION: ulsVersion,
            TIMESTAMP: timestamp
        };

        // Generate files
        const files = [
            {
                path: path.join(demoPagePath, 'features.jsx'),
                content: replaceTemplateVariables(TEMPLATES.features, templateVars)
            },
            {
                path: path.join(demoPagePath, 'import.js'),
                content: replaceTemplateVariables(TEMPLATES.import, templateVars)
            },
            {
                path: path.join(demoPagePath, 'DemoPage.jsx'),
                content: replaceTemplateVariables(TEMPLATES.demoPage, templateVars)
            },
            {
                path: path.join(componentPath, 'index.jsx'),
                content: `export { default } from './CustomBasicDemo';\n`
            },
            {
                path: path.join(componentPath, 'CustomBasicDemo.jsx'),
                content: replaceTemplateVariables(TEMPLATES.customComponent, templateVars)
            }
        ];

        // Create version tracking folder
        const syncPath = path.join(demoPagePath, '.uls-sync');
        fs.mkdirSync(syncPath, { recursive: true });
        
        files.push({
            path: path.join(syncPath, 'version.json'),
            content: replaceTemplateVariables(TEMPLATES.versionInfo, templateVars)
        });

        // Write files
        files.forEach(file => {
            fs.writeFileSync(file.path, file.content, 'utf8');
            console.log(`✅ Created: ${path.relative(process.cwd(), file.path)}`);
        });

        console.log(`\n🎉 Successfully generated custom demo page for ${componentName}!`);
        console.log(`\n📁 Generated structure:`);
        console.log(`   Custom demo: ${path.relative(process.cwd(), demoPagePath)}`);
        console.log(`   Custom component: ${path.relative(process.cwd(), componentPath)}`);
        console.log(`\n📝 Next steps:`);
        console.log(`   1. Add more custom demos in: ${componentPath}`);
        console.log(`   2. Update features.jsx to reference your demos`);
        console.log(`   3. Import DemoPage in your app routes`);
        console.log(`\n💡 The features.jsx automatically merges master features from ULS`);
        console.log(`   with your custom features. Your custom work is protected!`);
        console.log(`\n🚀 Your custom demo is ready to use!`);

    } catch (error) {
        console.error('\n❌ Error:', error.message);
        if (error.stack) {
            console.error('\nStack trace:', error.stack);
        }
        process.exit(1);
    }
}

// Run the generator
createCustomDemo();

